import numpy as np
from scipy import stats
from sklearn.cluster import AgglomerativeClustering

MAX_DRIVERS = 5

def design(feats):
    # Filter to only include features with significant effect sizes
    effect_sizes = np.abs([feats.x[:, feats.column(fid)] @ (feats.y - feats.y.mean()) 
                          for fid in feats.ids])
    sig_features = [fid for i, fid in enumerate(feats.ids) if abs(effect_sizes[i]) > 0.1]

    if not sig_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build correlation matrix for significant features
    X_sig = feats.x[:, [feats.column(fid) for fid in sig_features]]

    # Identify clusters using hierarchical clustering
    clustering = AgglomerativeClustering(n_clusters=2, linkage='ward').fit(X_sig)
    cluster_labels = clustering.labels_

    # Find dominant cluster
    if np.sum(cluster_labels == 0) > np.sum(cluster_labels == 1):
        module_features = [sig_features[i] for i in range(len(sig_features)) if cluster_labels[i] == 0]
    else:
        module_features = [sig_features[i] for i in range(len(sig_features)) if cluster_labels[i] == 1]

    if len(module_features) < 2:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Compute weighted loading based on effect sizes
    loadings = {}
    for fid in module_features:
        col_idx = feats.column(fid)
        loading = np.corrcoef(feats.x[:, col_idx], feats.y)[0, 1]
        loadings[fid] = loading

    # Return design with module features as drivers and loadings
    return Design(
        drivers=tuple(module_features[:min(MAX_DRIVERS, len(module_features))]),
        columns=tuple(module_features),
        products=(),
        loadings=loadings
    )
